// @ts-check
/**
 * Xcode 26 (iOS SDK 26) no longer accepts IPHONEOS_DEPLOYMENT_TARGET below
 * 15.0. Some podspecs still declare 12.x/13.x — and resource-bundle targets
 * such as AsyncStorage-AsyncStorage_resources are not covered by
 * react_native_post_install's clamp — so the build fails in Pods with
 * "deployment target ... is set to 13.0". Clamp every Pods target to the
 * Podfile platform version. The Podfile is generated by `expo prebuild`, so
 * the fix must come through a config plugin rather than editing ios/ output.
 */
const { withPodfile, withPodfileProperties } = require('@expo/config-plugins');

const CLAMP_SNIPPET = `
    # Clamp deployment targets on every Pods target (incl. resource bundles)
    # to the Podfile platform — Xcode 26 rejects targets pinned below 15.0.
    min_target = podfile_properties['ios.deploymentTarget'] || '16.4'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |bc|
        current = bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        bc.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = min_target if current.nil? || Gem::Version.new(current) < Gem::Version.new(min_target)
        # RN 0.87's prebuilt React.framework umbrella headers include yoga/JSRuntimeFactory
        # headers CocoaPods stages outside the module — allow the non-modular includes.
        bc.build_settings['CLANG_ALLOW_NON_MODULAR_INCLUDES_IN_FRAMEWORK_MODULES'] = 'YES'
      end
    end
`;

/** @type {import('@expo/config-plugins').ConfigPlugin} */
module.exports = function withIosDeploymentTargetClamp(config) {
  // RN 0.87 defaults to prebuilt React.xcframework binaries, which flips
  // EXPO_USE_PRECOMPILED_MODULES on — and the shipped ExpoModulesCore
  // xcframework was compiled against RN 0.86-era headers, so Fabric's
  // RawPropsParser::prepare<ExpoViewProps> aborts at app launch. Building
  // React from source also forces every Expo module to compile against the
  // real 0.87 headers.
  config = withPodfileProperties(config, (cfg) => {
    cfg.modResults['ios.buildReactNativeFromSource'] = 'true';
    return cfg;
  });
  return withPodfile(config, (cfg) => {
    if (!cfg.modResults.contents.includes('min_target = podfile_properties')) {
      cfg.modResults.contents = cfg.modResults.contents.replace(
        /(post_install do \|installer\|[\s\S]*?react_native_post_install\([\s\S]*?\n    \)\n)/,
        `$1${CLAMP_SNIPPET}`
      );
    }
    return cfg;
  });
};
